import type { ChartOptions } from 'chart.js';

import type { PortfolioPieChartData } from '../../../types';

export const PORTFOLIO_PIE_CHART_COLORS_BY_ID: Record<
  PortfolioPieChartData['id'],
  readonly string[]
> = {
  liquidType: [
    '#FDD349',
    '#E2D4BB',
    '#99D6FF',
    '#FFBA8F',
    '#7AEAF0',
    '#D2BEF4',
  ],
  innovationPillar: ['#FDD349', '#99D6FF', '#CBCAC7'],
  megabrandFramework: ['#EBB400', '#70C6FF', '#C9AF82', '#B5B4AF'],
};

const WORK_SANS = "'Work Sans', sans-serif";

export const PORTFOLIO_PIE_CHART_HEIGHT = 263;

export const PORTFOLIO_PIE_CHART_OPTIONS: ChartOptions<'doughnut'> = {
  layout: {
    padding: { top: 36, bottom: 40, left: 48, right: 48 },
  },
  plugins: {
    datalabels: {
      clip: false,
      offset: 8,
      display: ({ dataIndex, dataset }) =>
        dataset.data[dataIndex] === 0 ? false : 'auto',
      font: {
        size: 18,
        family: WORK_SANS,
        lineHeight: 1.4,
        weight: 500,
      },
    },
    tooltip: {
      titleFont: {
        family: WORK_SANS,
        size: 12,
        weight: 400,
      },
      bodyFont: {
        family: WORK_SANS,
        size: 12,
        weight: 400,
      },
    },
  },
};
